		const rawPhone = phoneCol !== -1 ? row[phoneCol] || "" : "";
		const rawDept = deptCol !== -1 ? row[deptCol] || "Geral" : "Geral";
		const rawDate = row[dateCol] || "";
		const rawStart = row[startCol] || "";
		const rawEnd = row[endCol] || "";
